import test from'node:test';import assert from'node:assert/strict';import{bootstrapATO,SEED_PROFILE}from'../src/index.mjs';
test('generic setup boots with Klein organs, Success, and Conversation now',()=>{const system=bootstrapATO();assert.equal(system.status,'ready');assert.deepEqual(system.profile,SEED_PROFILE);assert.equal(system.tools.length,13);assert.deepEqual([...system.mesh.automatons.keys()].sort(),['autoling','autonovel','browser-form','computational-grammar-coder','conversation','diseminer','historical-monte-carlo','iching-grammar','klein-analogy','language-contact','messy','research-browser','success']);assert.equal(system.manifests.every(x=>x.addressKey),true);});
test('a supplied personal profile changes setup qualities without changing Tool identity',()=>{const generic=bootstrapATO(),personal=bootstrapATO({profile:{id:'p',version:'personal.v1',personalized:true,qualities:{expression:'fluid'},provenance:'person'}});assert.deepEqual(personal.tools.map(x=>x.id),generic.tools.map(x=>x.id));assert.equal(personal.profile.qualities.expression,'fluid');});
